inline bool chkmin(T& x, const T& y) {
    return x <= y ? false : (x = y, true);
}

template <typename T>
inline T scan(T& in) {
    in = 0;
    int ch = getchar();
    T sign = 1;
    while (ch < '0' || ch > '9') {
        if (ch == '-') sign = -1;
        ch = getchar();
