using Color = pair<int, int>;

static const int MAXM = 5000 + 11;
static const Color INF = make_pair(1000000000, 0);

int n, m, q;
int color;

inline int node_id(int l, int r) {
    return (l + r) | (l != r);
}

class SegmentTree {
private:
    Color value[MAXM];

public:
    SegmentTree() {
        FOR(i, 0, MAXM - 1)
            value[i] = INF;
    }

    void modify(int l, int r, int L, int R, const Color& c) {
        int rt = node_id(l, r);

        if (L <= l && r <= R) {
            chkmin(value[rt], c);
            return;
        }

        int mid = (l + r) >> 1;
        if (L <= mid)
            modify(l, mid, L, R, c);
        if (R > mid)
            modify(mid + 1, r, L, R, c);
    }

    Color query(int l, int r, int x) const {
        int rt = node_id(l, r);
        Color result = value[rt];

        if (l == r)
            return result;

        int mid = (l + r) >> 1;
        if (x <= mid)
            chkmin(result, query(l, mid, x));
        else
            chkmin(result, query(mid + 1, r, x));

        return result;
    }
};

SegmentTree trees[MAXM];

