            int x, int y, const Color& c) {
    int rt = node_id(l, r);

    if (L <= l && r <= R) {
        trees[rt].modify(1, m, x, y, c);
        return;
    }

    int mid = (l + r) >> 1;
    if (L <= mid)
        modify(l, mid, L, R, x, y, c);
    if (R > mid)
