using namespace std;

class FastInput {
public:
    template <typename T>
    bool read(T& value) {
        value = 0;
        int sign = 1;
        int ch = getchar_unlocked();

        while (ch != EOF && (ch < '0' || ch > '9')) {
            if (ch == '-') sign = -1;
            ch = getchar_unlocked();
        }
        if (ch == EOF) return false;

        while (ch >= '0' && ch <= '9') {
            value = value * 10 + (ch - '0');
            ch = getchar_unlocked();
        }

        value *= sign;
        return true;
    }
};

using Value = uint64_t;

static constexpr uint32_t CHUNK_BITS = 18;
static constexpr uint32_t CHUNK_SIZE = 1u << CHUNK_BITS;
static constexpr uint32_t CHUNK_MASK = CHUNK_SIZE - 1;
static constexpr Value INF_VALUE =
    (static_cast<Value>(1000000000u) << 32);

inline Value makeValue(uint32_t area, uint32_t color) {
    return (static_cast<Value>(area) << 32) | color;
}

inline uint32_t getColor(Value value) {
    return static_cast<uint32_t>(value);
}

struct Node {
    uint32_t left;
    uint32_t right;
    Value value;
};

class NodePool {
private:
    vector<Node*> chunks;
    uint32_t size_ = 1;

    void addChunk() {
        Node* chunk = new Node[CHUNK_SIZE];
        chunks.push_back(chunk);
    }

public:
    NodePool() {
        addChunk();
        chunks[0][0] = {0, 0, INF_VALUE};
    }

    ~NodePool() {
        for (Node* chunk : chunks) delete[] chunk;
    }

    Node& operator[](uint32_t index) {
        return chunks[index >> CHUNK_BITS][index & CHUNK_MASK];
    }

    uint32_t create() {
        if ((size_ & CHUNK_MASK) == 0) addChunk();
        uint32_t index = size_++;
        (*this)[index] = {0, 0, INF_VALUE};
        return index;
    }
};

class SparseTwoDimensionalTree {
private:
    int n;
    int m;
    vector<uint32_t> roots;
    NodePool pool;

    static int nodeIndex(int left, int right) {
        return (left + right) | (left != right);
    }

    void modifyY(uint32_t& root, int left, int right,
                 int queryLeft, int queryRight, Value value) {
        if (root == 0) root = pool.create();

        Node& node = pool[root];
        if (node.value <= value) return;

        if (queryLeft <= left && right <= queryRight) {
            node.value = value;
            return;
        }

        int middle = (left + right) >> 1;

        if (queryLeft <= middle) {
            uint32_t child = node.left;
            modifyY(child, left, middle, queryLeft, queryRight, value);
            pool[root].left = child;
        }

        if (queryRight > middle) {
            uint32_t child = pool[root].right;
            modifyY(child, middle + 1, right,
                    queryLeft, queryRight, value);
            pool[root].right = child;
        }
    }

    Value queryY(uint32_t root, int left, int right, int position) {
        if (root == 0) return INF_VALUE;

        Value result = pool[root].value;
        if (left == right) return result;

        int middle = (left + right) >> 1;
        if (position <= middle) {
            return min(result, queryY(pool[root].left, left, middle, position));
        }
        return min(result,
                   queryY(pool[root].right, middle + 1, right, position));
    }

    void modifyX(int left, int right, int queryLeft, int queryRight,
                 int y1, int y2, Value value) {
        int index = nodeIndex(left, right);

        if (queryLeft <= left && right <= queryRight) {
            modifyY(roots[index], 1, m, y1, y2, value);
            return;
        }

        int middle = (left + right) >> 1;
        if (queryLeft <= middle) {
            modifyX(left, middle, queryLeft, queryRight, y1, y2, value);
        }
        if (queryRight > middle) {
            modifyX(middle + 1, right, queryLeft, queryRight,
                    y1, y2, value);
        }
    }

    Value queryX(int left, int right, int x, int y) {
        int index = nodeIndex(left, right);
        Value result = queryY(roots[index], 1, m, y);

        if (left == right) return result;

        int middle = (left + right) >> 1;
        if (x <= middle) {
            return min(result, queryX(left, middle, x, y));
        }
        return min(result, queryX(middle + 1, right, x, y));
    }

public:
    SparseTwoDimensionalTree(int rows, int columns)
        : n(rows), m(columns), roots(2 * rows + 5, 0) {}

    void modify(int x1, int x2, int y1, int y2, Value value) {
        modifyX(1, n, x1, x2, y1, y2, value);
    }

    Value query(int x, int y) {
        return queryX(1, n, x, y);
    }
};

