    uint32_t color = 1;

    tree.modify(1, n, 1, m,
                makeValue(static_cast<uint32_t>(n * m), color));

    while (q--) {
        int operation, x1, y1, x2, y2;
        input.read(operation);
        input.read(x1);
        input.read(y1);
        input.read(x2);
        input.read(y2);

        if (operation == 3) {
            puts(getColor(tree.query(x1, y1)) ==
                         getColor(tree.query(x2, y2))
                     ? "Yes"
                     : "No");
            continue;
        }

        if (x1 > x2) swap(x1, x2);
        if (y1 > y2) swap(y1, y2);

        uint32_t area = static_cast<uint32_t>(
            static_cast<int64_t>(x2 - x1 + 1) * (y2 - y1 + 1));

        if (operation == 1) {
            tree.modify(x1, x2, y1, y2, makeValue(area, ++color));
        } else {
            uint32_t inheritedColor =
                getColor(tree.query(x1 - 1, y1 - 1));
            tree.modify(x1, x2, y1, y2,
                        makeValue(area, inheritedColor));
        }
    }

    return 0;
}

