inline int def( int l , int r ) { return l + r | l != r ; }

class segment_tree {
	private :
		__ col[maxm] ;
		__ tag[maxm] ;
	public :

		segment_tree() {
			FOR( i , 0 , maxm - 1 )
				col[i] = tag[i] = make_pair( 1e9 , 0 ) ;
		}

		void modify( int l , int r , int L , int R , __ c ) {
			int rt = def( l , r ) ;
			if( l >= L && r <= R ) {
				if( chkmin( col[rt] , c ) ) tag[rt] = c ;
				return ;
			}
			int mid = l + r >> 1 ;
			if( mid >= L ) modify( l , mid , L , R , c ) ;
			if( mid < R ) modify( mid + 1 , r , L , R , c ) ;
		}

		__ query( int l , int r , int x ) {
			int rt = def( l , r ) ;
			if( l == r ) return col[rt] ;
			int mid = l + r >> 1 ; __ res = tag[rt] ;
			if( x <= mid ) chkmin( res , query( l , mid , x ) ) ;
			else chkmin( res , query( mid + 1 , r , x ) ) ;
			return res ;
		}

} T[maxm] ;

namespace Segment_tree {

	void modify( int l , int r , int L , int R , int x , int y , __ c ) {
		int rt = def( l , r ) ;
		if( l >= L && r <= R )
			return T[rt].modify( 1 , m , x , y , c ) ;
		int mid = l + r >> 1 ;
		if( mid >= L ) modify( l , mid , L , R , x , y , c ) ;
		if( mid < R ) modify( mid + 1 , r , L , R , x , y , c ) ;
	}

	__ query( int l , int r , int x , int y ) {
		int rt = def( l , r ) ;
		if( l == r ) return T[rt].query( 1 , m , y ) ;
		int mid = l + r >> 1 ; __ res = T[rt].query( 1 , m , y ) ;
		if( x <= mid ) chkmin( res , query( l , mid , x , y ) ) ;
		else chkmin( res , query( mid + 1 , r , x , y ) ) ;
		return res ;
	}

} using namespace Segment_tree ;

